uint32_t rotl32(uint32_t x, unsigned n)
{
    n &= 31u;                                    /* rotation is modulo 32 */
    /* (32 - n) & 31 is 0 when n == 0: both halves are x, x | x == x. No shift by 32. */
    return (x << n) | (x >> ((32u - n) & 31u));
}

uint32_t rotr32(uint32_t x, unsigned n)
{
    n &= 31u;
    return (x >> n) | (x << ((32u - n) & 31u));
}

