    printf("%d %d\n", n >> 1, n / 2);
    printf("%d %u\n", -1 >> 31, (unsigned)-1 >> 28);
    printf("%X %X\n", (unsigned)(s >> 4), (unsigned)((uint8_t)s >> 4));
    return 0;
}
