        int32_t delta;
        if (scanf("%d", &delta) != 1) return 0;
        if (checked_add_i32(charge, delta, &charge))
            printf("%d\n", charge);
        else
            printf("OVERFLOW (kept %d)\n", charge);
    }
    return 0;
